import {Application,Vault} from '@offtree/effectory-sdk';
import {Effect,Schema} from 'effect';
const record=(phase)=>Effect.sync(()=>appendFileSync(${JSON.stringify(marker)},phase+'\\n'));
const Credentials=Vault.make({id:'credentials',secrets:{token:Schema.String}});
const provider=Vault.layer(Credentials,()=>Effect.acquireRelease(
 record('provider-acquired').pipe(Effect.as({providerId:'test/shutdown',read:()=>record('reading').pipe(Effect.andThen(Effect.never),Effect.ensuring(Effect.gen(function*(){
 yield* record('read-cleanup-start');
 while(!existsSync(${JSON.stringify(gate)})) yield* Effect.sleep('5 millis');
